/**
 * Emoji, offline (docs/design/captions-studio.md §11.3): suggestions from the words, the
 * sensitive-topic guard, and emoji keys. The words come from emojiData.ts (generated by
 * scripts/build-emoji-data.mjs); the emoji that can be drawn from emojiList.ts. Pure.
 */
import { GRAPHIC_DEFAULTS } from '../render/graphics'
import type { EmojiGraphic, Project } from '../types'
import { EMOJI_TRIGGERS } from './emojiData'
import { EMOJI_KEYS } from './emojiList'
import { bareWord } from './numbers'
import { studioTokens } from './words'
import { graphicId } from './graphicRules'

/** At most one emoji per this many seconds (§11.3). */
export const EMOJI_EVERY = 8
/** A graphic starts this long before its word (§10.2). */
export const LEAD = 0.1

const baseLanguage = (language: string | undefined): string => (language ?? 'en').toLowerCase().split(/[-_]/)[0]

/** The key of an emoji as typed: code points in hex joined by '-', without FE0F. */
export function emojiKey(emoji: string): string {
  return [...emoji]
    .map((c) => c.codePointAt(0)!)
    .filter((c) => c !== 0xfe0f)
    .map((c) => c.toString(16))
    .join('-')
}

/** Never suggested, even if a list names them (§11.3). */
const NEVER = new Set(['🔪', '🔫', '💣', '🍆', '🍑', '💦', '🖕', '💩', '⚰️', '🩸', '💀', '☠️'].map(emojiKey))

/** Word endings a trigger may take (§11.3); other languages match whole words. */
const SUFFIXES: Readonly<Record<string, readonly string[]>> = {
  en: ['s', 'es', 'ed', 'ing', 'er', 'ers', 'ly'],
  bn: ['টি', 'টা', 'গুলো', 'দের', 'ের', 'কে', 'তে', 'ে'],
  hi: ['ों', 'ें', 'ी', 'ा', 'े'],
  es: ['s', 'es'],
  fr: ['s', 'x', 'e', 'es'],
  de: ['e', 'en', 'er', 'es', 'n', 's'],
  pt: ['s', 'es']
}

/** Negations: a caption with one gets no emoji (§11.3: "We are not happy with the old price"). */
const NEGATIONS: Readonly<Record<string, readonly string[]>> = {
  en: ['not', 'never', 'no', "don't", 'dont', "doesn't", "didn't", "isn't", "aren't", "wasn't", "weren't", "won't", "can't", 'cannot', "shouldn't", "wouldn't", 'nothing', 'nobody', 'none'],
  bn: ['না', 'নয়', 'নেই', 'নি'],
  hi: ['नहीं', 'न', 'मत'],
  es: ['no', 'nunca', 'jamás', 'nada'],
  fr: ['ne', 'pas', 'jamais', 'rien'],
  de: ['nicht', 'nie', 'niemals', 'kein', 'keine', 'nichts'],
  pt: ['não', 'nunca', 'jamais', 'nada']
}

/**
 * Sensitive topics (Written for Flown, CC0-1.0; native speakers check bn and hi): a caption with
 * one gets no emoji or keyword pop-up (§11.3). Each matches a word that starts with it.
 */
const SENSITIVE: Readonly<Record<string, readonly string[]>> = {
  en: [
    'died', 'death', 'dead', 'dying', 'cancer', 'war', 'wars', 'accident', 'funeral', 'abuse', 'abused', 'suicide', 'attack', 'disaster', 'killed', 'murder', 'shooting',
    'terror', 'rape', 'assault', 'disease', 'grief', 'mourning', 'tragedy', 'tragic', 'victim', 'injured', 'injury', 'crash', 'bomb', 'violence', 'violent', 'overdose',
    'depression', 'genocide', 'massacre', 'hostage', 'kidnap', 'passed away', 'pandemic', 'earthquake', 'flood', 'famine', 'refugee', 'cancer', 'tumor', 'tumour'
  ],
  bn: ['মৃত্যু', 'মারা', 'মৃত', 'ক্যান্সার', 'যুদ্ধ', 'দুর্ঘটনা', 'জানাজা', 'আত্মহত্যা', 'হামলা', 'দুর্যোগ', 'ধর্ষণ', 'হত্যা', 'খুন', 'নির্যাতন', 'শোক', 'বন্যা', 'ভূমিকম্প'],
  hi: ['मौत', 'मृत्यु', 'मरा', 'मरी', 'मरे', 'कैंसर', 'युद्ध', 'दुर्घटना', 'संस्कार', 'आत्महत्या', 'हमला', 'आपदा', 'बलात्कार', 'हत्या', 'शोक', 'बाढ़', 'भूकंप'],
  es: ['murió', 'muerte', 'muerto', 'cáncer', 'guerra', 'accidente', 'funeral', 'abuso', 'suicidio', 'ataque', 'desastre', 'asesinato', 'violación', 'víctima'],
  fr: ['mort', 'décès', 'décédé', 'cancer', 'guerre', 'accident', 'funérailles', 'obsèques', 'abus', 'suicide', 'attaque', 'catastrophe', 'meurtre', 'viol', 'victime'],
  de: ['gestorben', 'tod', 'tot', 'krebs', 'krieg', 'unfall', 'beerdigung', 'missbrauch', 'selbstmord', 'suizid', 'angriff', 'katastrophe', 'mord', 'vergewaltigung', 'opfer'],
  pt: ['morreu', 'morte', 'morto', 'câncer', 'cancro', 'guerra', 'acidente', 'funeral', 'abuso', 'suicídio', 'ataque', 'desastre', 'assassinato', 'estupro', 'vítima']
}
/** English sensitive words that also start harmless words, matched whole or with a suffix only. */
const WHOLE = new Set(['war', 'wars', 'dead', 'died', 'crash', 'flood', 'tod', 'tot', 'mort', 'viol', 'mord', 'opfer'])

/** Whether `word` (bare) is `stem` or `stem` with one of the language's endings. */
function wordForm(word: string, stem: string, lang: string): boolean {
  if (word === stem) return true
  if (!word.startsWith(stem)) return false
  const rest = word.slice(stem.length)
  return (SUFFIXES[lang] ?? []).includes(rest)
}

/** Whether a caption is about a sensitive topic (no emoji or keyword pop-ups on it). */
export function isSensitive(text: string, language?: string): boolean {
  const lang = baseLanguage(language)
  const lower = text.toLocaleLowerCase()
  const words = lower.split(/\s+/).map(bareWord).filter(Boolean)
  const own = SENSITIVE[lang] ?? []
  for (const s of own) {
    if (/\s/.test(s)) {
      if (lower.includes(s)) return true
      continue
    }
    for (const w of words) if (WHOLE.has(s) ? wordForm(w, s, lang) : w.startsWith(s)) return true
  }
  // English words in a caption in another language count whole ("bomb", not "bombilla").
  if (lang !== 'en') for (const s of SENSITIVE.en) for (const w of words) if (wordForm(w, s, 'en')) return true
  return false
}

/** Whether a caption says no to something (no emoji on it). */
function negated(words: readonly string[], lang: string): boolean {
  const list = new Set([...(NEGATIONS[lang] ?? []), ...(lang === 'en' ? [] : NEGATIONS.en)])
  return words.some((w) => list.has(w) || (lang === 'en' && /n't$/.test(w)))
}

/** The emoji key a word triggers in `lang`, or null. */
export function emojiForWord(word: string, language?: string): string | null {
  const lang = baseLanguage(language)
  const table = EMOJI_TRIGGERS[lang] ?? EMOJI_TRIGGERS.en
  const w = bareWord(word)
  if (!w) return null
  const exact = table[w]
  if (exact) return exact
  for (const suffix of SUFFIXES[lang] ?? []) {
    if (w.length <= suffix.length || !w.endsWith(suffix)) continue
    const stem = table[w.slice(0, -suffix.length)]
    if (stem) return stem
  }
  return null
}

const CAPITAL = /^[^\p{L}]*\p{Lu}/u
const SENTENCE_END = /[.!?…।。！？]["'”’)\]]*$/u

/** Emoji anchored to their words, at most one per 8 s, with the guards of §11.3. */
export function suggestEmoji(project: Project): EmojiGraphic[] {
  const transcript = project.transcript
  if (!transcript?.segments.length) return []
  const language = transcript.language
  const lang = baseLanguage(language)
  const speakers = new Set(transcript.segments.flatMap((s) => (s.speaker ? s.speaker.toLocaleLowerCase().split(/\s+/) : [])))
  const marked = new Map<string, Set<number>>()
  for (const m of project.captionMarks ?? []) {
    const set = marked.get(m.caption) ?? new Set<number>()
    for (let i = m.from; i <= m.to; i++) set.add(i)
    marked.set(m.caption, set)
  }
  const d = GRAPHIC_DEFAULTS.emoji
  const out: EmojiGraphic[] = []
  let last = -Infinity
  for (const seg of transcript.segments) {
    if (!seg.text.trim() || isSensitive(seg.text, language)) continue
    const tokens = studioTokens(seg, language).filter((t) => t.word >= 0)
    const bare = tokens.map((t) => bareWord(t.text))
    if (negated(bare, lang)) continue
    const found: { i: number; key: string }[] = []
    tokens.forEach((t, i) => {
      const key = emojiForWord(t.text, language)
      if (!key || NEVER.has(key) || !EMOJI_KEYS.has(key)) return
      // Names: a capitalised word next to another ("Apple Notes"), and a speaker's name.
      const capAt = (k: number): boolean => k >= 0 && k < tokens.length && CAPITAL.test(tokens[k].text)
      const name = CAPITAL.test(t.text) && ((capAt(i + 1) && !SENTENCE_END.test(t.text)) || (capAt(i - 1) && !SENTENCE_END.test(tokens[i - 1].text)))
      if (name) return
      if (speakers.has(bare[i])) return
      found.push({ i, key })
    })
    if (!found.length) continue
    // An emphasised word first, else the first word with an emoji.
    const emphasised = marked.get(seg.id)
    const pick = found.find((f) => emphasised?.has(tokens[f.i].word)) ?? found[0]
    const t = tokens[pick.i]
    const start = Math.max(0, t.start - LEAD)
    if (start - last < EMOJI_EVERY) continue
    last = start
    const text = t.text.slice(0, 80)
    out.push({
      id: graphicId('emoji', seg.id, t.word, pick.key),
      kind: 'emoji',
      emoji: pick.key,
      start,
      end: Math.min(project.duration > 0 ? project.duration : Infinity, start + d.length),
      place: 'auto',
      size: d.size,
      enter: { ...d.enter },
      exit: { ...d.exit },
      anchor: { caption: seg.id, from: t.word, to: t.word, text },
      auto: { by: 'emoji', via: 'rules', caption: seg.id }
    })
  }
  return out
}
